contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint lockTime, uint minSum, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(0xdead)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Put{value: amount}(lockTime); if (__ESBMC_reverted()) return;

        (uint unlock, uint bal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        uint collectAmt;
        uint cBalBefore = address(c).balance;
        bool reverted;
        c.Collect(collectAmt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        (uint unlockAfter, uint balAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        assert(reverted ? (balAfter == bal && unlockAfter == unlock && address(c).balance == cBalBefore) : (balAfter == bal - collectAmt && unlockAfter == unlock && address(c).balance == cBalBefore - collectAmt));
    }
}

