pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 lockTime, uint256 minSum, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(address(0xdead)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Put{value: amount}(lockTime) {} catch { return; }
        uint256 unlock;
        uint256 bal;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlock = __r0; bal = __r1; } catch { return; }
        uint collectAmt;
        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 unlockAfter;
        uint256 balAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockAfter = __r0; balAfter = __r1; } catch { return; }
        assertTrue(reverted ? (balAfter == bal && unlockAfter == unlock && address(c).balance == cBalBefore) : (balAfter == bal - collectAmt && unlockAfter == unlock && address(c).balance == cBalBefore - collectAmt));
    }

    function testFuzz_run(uint256 lockTime, uint256 minSum, uint256 amount) public {
        _run(lockTime, minSum, amount);
    }

    receive() external payable {}
}
